head.script:
// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);

    // 기본값 세팅
    scwin.setDefaultVal();

    // 시스템권한 가리기
    if (js_id.indexOf("sysm") === -1) {
        label_2.hide();
        cmb_pACNT_DIV.hide();
        label_4.hide();
        txb_pASUM_ACNT.hide();
        btn_search_realtime.hide();
    }
    const array_grid = [grd_List];
    setResizeGrid(array_grid);
    await scwin.ins_search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_TRD_DD_onclick
 * @description img_TRD_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_TRD_DD_onclick = function() {
    try {
        popUpCalendar2(edt_TRD_DD_START);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS31200.img_TRD_DD_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31200.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        }
        scwin.setBgColorList(); // 그리드 배경색 설정
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31200.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31200.btn_search_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        alert_tr_error(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS31200.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));

        // 재조회
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31200.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name grd_List_onheadcheckclick
 * @description grd_List onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_onheadcheckclick = function(col, colid, bCheck) {
    try {
        fn_CheckAll(bCheck);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS31200.grd_List_onheadcheckclick" });
    }
};

/**
 * @method
 * @name grd_List_oncheckclick
 * @description grd_List oncheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_oncheckclick = function(col, colid, bCheck) {
    try {
        fn_Check(col, bCheck, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS31200.grd_List_oncheckclick" });
    }
};

/**
 * @method
 * @name img_TO_TRNSM_DD_onclick
 * @description img_TO_TRNSM_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_TO_TRNSM_DD_onclick = function() {
    try {
        popUpCalendar2(edt_TRD_DD_END);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS31200.img_TO_TRNSM_DD_onclick" });
    }
};

/**
 * @method
 * @name txb_pDEPOPRN_NM_onkeyup
 * @description txb_pDEPOPRN_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_pDEPOPRN_NM_onkeyup = async function() {
    try {
        fn_DelChar(this);
        if (txb_pDEPOPRN_NM.getValue() === "") {

        } else {
            if (window.event.keyCode === 13) {
                await scwin.ins_search();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31200.txb_pDEPOPRN_NM_onkeyup" });
    }
};

/**
 * @method
 * @name btn_search_realtime_onclick
 * @description 「미리보기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_realtime_onclick = async function() {
    try {
        await scwin.ins_search_realtime();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS31200.btn_search_realtime_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!await scwin.chkValid("ins_search")) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    const sToday = $c.ut.cGetToday2();
    edt_TRD_DD_START.setValue(sToday);
    edt_TRD_DD_END.setValue(sToday);
    panel_5.hide();
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_List.removeAll();
    txb_TotalCnt.setValue("총 0건");
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === "ins_search") {
        if (edt_TRD_DD_START.getValue() === "") {
            await $c.win.alert("거래일자 시작일을 입력하세요.");
            edt_TRD_DD_START.focus();
            return false;
        }
        if (edt_TRD_DD_END.getValue() === "") {
            await $c.win.alert("거래일자 종료일을 입력하세요.");
            edt_TRD_DD_END.focus();
            return false;
        }
    } else if (pGubun === "ins_search_realtime") {
        if (edt_TRD_DD_START.getValue() === "") {
            await $c.win.alert("거래일자 시작일을 입력하세요.");
            edt_TRD_DD_START.focus();
            return false;
        }
        if (edt_TRD_DD_END.getValue() === "") {
            await $c.win.alert("거래일자 종료일을 입력하세요.");
            edt_TRD_DD_END.focus();
            return false;
        }
        if (txb_pDEPOPRN_NM.getValue() !== "") {
            await $c.win.alert("미리보기 조회시 [거래자성명]은 사용 할 수 없습니다.");
            txb_pDEPOPRN_NM.focus();
            return false;
        }
        if (cmb_pACNT_DIV.getValue() === "2") {
            if (txb_pASUM_ACNT.getValue() !== "") {
                await $c.win.alert("선납계좌 선택시 [가상계좌]는 사용 할 수 없습니다.");
                txb_pASUM_ACNT.focus();
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name ins_search_realtime
 * @description 실시간 sap 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search_realtime = async function() {
    await $c.win.alert('[미리보기] 기능은 실시간 계좌조회 용도이며 시스템관리자 권한에서만 활성화됩니다.');

    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!await scwin.chkValid("ins_search_realtime")) {
        return;
    }

    // Lodaing~~~ 표시
    const url = "/PrepayInfoAction.do?SCREN_ID=" + "ULDINS31200.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=sapRealTimeSearch" + "&outputMessageId=INS_LIST_DEPO_CONFRM_RCV_DTL_LIST_INQUIRY" + "&service=krx.lds.ins.etc.services.PrepayInfoApp" +
        // "&queryId=lds.ins.search.select.TBLD_B_DEPO_CONFRM_RCV_DTL.dtl" +
        "&TRD_DD=" + edt_TRD_DD_START.getValue() + "&TRD_DD_END=" + edt_TRD_DD_END.getValue() + "&DEPOPRN_NM=" + txb_pDEPOPRN_NM.getValue() + "&ASUM_ACNT=" + txb_pASUM_ACNT.getValue() + "&ACNT_DIV=" + cmb_pACNT_DIV.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};

/**
 * @method
 * @name getParam
 * @description 발생기관 팝업에서 값 받음.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue();
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setBgColorList
 * @description 미확정 목록의 배경색 설정
 * @returns {void}
 * @hidden N
 */
scwin.setBgColorList = function() {
    // 그리드 컬럼 ID 구하기
    const arrColID = [];
    for (let i = 0; i < grd_List.getTotalCol(); i++) {
        arrColID.push(grd_List.getColumnID(i));
    }

    // 입금전에 코드 발급한 건의 배경색 Light Yellow로 설정
    for (let j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_List, arrColID[j], 'BgColor', "{decode(VALID_YN,'N','#FF9900',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};

/**
 * @method
 * @name grd_List_CanColumnPosChange
 * @description grd List Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
